UPDATE pdm_spu SET sku = #{sku}, title = #{title}, description = #{description}, category_id = #{categoryId},
brand_id = #{brandId}, status = #{status}, ip_status = #{ipStatus}, updated_at = #{updatedAt}
WHERE spu_id = #{spuId} AND tenant_id = #{tenantId}

UPDATE pdm_sku SET title = #{title}, weight_kg = #{weightKg}, declared_value = #{declaredValue},
currency = #{currency}, status = #{status}, updated_at = #{updatedAt}
WHERE sku_id = #{skuId} AND tenant_id = #{tenantId}

UPDATE pdm_selection_proposal SET product_name = #{productName}, title = #{title}, category_id = #{categoryId},
source = #{source}, source_reference = #{sourceReference}, estimated_cost = #{estimatedCost},
market_analysis = #{marketAnalysis}, profit_estimation = #{profitEstimation}, risk_assessment = #{riskAssessment},
ai_suggested = #{aiSuggested}, status = #{status}, submitted_by = #{submittedBy},
reviewed_by = #{reviewedBy}, review_comment = #{reviewComment}, updated_at = #{updatedAt}
WHERE proposal_id = #{proposalId} AND tenant_id = #{tenantId}

UPDATE pdm_product_development SET proposal_id = #{proposalId}, stage = #{stage}, stage_note = #{stageNote},
developer = #{developer}, editor = #{editor}, designer = #{designer}, priority = #{priority},
status = #{status}, updated_at = #{updatedAt}
WHERE dev_id = #{devId} AND tenant_id = #{tenantId}
